pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 fuzzBlockNumber, uint256 deltaTimestamp) public {
        uint256 bn = bound(fuzzBlockNumber, 1, type(uint256).max - 1);
        uint256 dt = bound(deltaTimestamp, 1, 1 days);

        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);

        vm.warp(1);

        vm.roll(bn);
        vm.warp(block.timestamp + dt);

        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        bool drainedByRef = (bn % 15 == 0);

        uint256 expected = drainedByRef ? 0 : 10 ether;
        assertTrue(address(c).balance == expected);
    }
}
